  var unkOut = null;
  if (unk) {
    var uc = ctr(unk), udist = 99;
    if (pac) udist = r1(Math.abs(wrapd(uc.x - pac.x)) + Math.abs(uc.y - pac.y));
    unkOut = { x: r1(uc.x), y: r1(uc.y), w: r1((unk.x1 - unk.x0 + 1) / sx), h: r1((unk.y1 - unk.y0 + 1) / sy), n: unk.n, dist: udist };
  }
  return { visible: pac ? 1 : 0, pac: pac ? [r1(pac.x), r1(pac.y)] : null, heading: m.heading, up: A.up, down: A.down, left: A.left, right: A.right, nearGhost: nearGhost, ghosts: gh.length, blue: fr.length, flashing: flashing, blueTicks: m.blueT, pellets: remain, eaten: Math.max(0, m.maxPel - remain), level: m.level, lives: Math.max(0, 3 - m.deaths), over: isOver(), unknown: unkOut };
}

