function teach(s) {
  var ids = ['up', 'down', 'left', 'right'], i, a, o, best = null;
  var cur = { N: 'up', S: 'down', W: 'left', E: 'right' }[s.heading] || null;
  var open = [], hunt = [], safe = [];
  for (i = 0; i < 4; i++) if (s[ids[i]] && s[ids[i]].open) open.push(ids[i]);
  if (!s.visible || s.over || !open.length) return cur || { up: 0.25, down: 0.25, left: 0.25, right: 0.25 };
  for (i = 0; i < open.length; i++) { if (s[open[i]].room >= 3) hunt.push(open[i]); if (s[open[i]].room >= 8) safe.push(open[i]); }
  // the action of a list with the smallest value of field f, among those with f <= lim
  function smallest(list, f, lim) {
    var bb = null;
    for (var z = 0; z < list.length; z++) { var q = list[z]; if (s[q][f] <= lim && (bb === null || s[q][f] < s[bb][f])) bb = q; }
    return bb;
  }
  // 1. hunt a close blue ghost that is safely reachable
  best = smallest(hunt, 'prey', s.flashing ? 5 : 12);
  if (best) return best;
  if (safe.length) {
    // 2. power pellets are kept for when they pay off: eat one when a ghost closes in, or when every pellet left is past a ghost
    var pw = smallest(safe, 'power', 8);
    if (!s.blue && pw && (s.nearGhost <= 7 || (pw === cur && s.nearGhost <= 10))) return pw;
    var allFar = true;
    for (i = 0; i < safe.length; i++) if (s[safe[i]].food < 60) allFar = false;
    if (allFar) { best = smallest(safe, 'power', 59.9); if (best) return best; }
    // 3. the nearest ordinary pellet, keeping the heading on near ties; with none left, the nearest power pellet
    best = null;
    for (i = 0; i < safe.length; i++) { a = safe[i]; o = s[a]; if (!best || o.food < s[best].food || (o.food === s[best].food && o.ghost > s[best].ghost)) best = a; }
    if (s[best].food >= 99) { a = smallest(safe, 'power', 98.9); if (a) return a; }
    if (cur && safe.indexOf(cur) >= 0 && s[cur].food <= s[best].food + 0.5) return cur;
    return best;
  }
  // 4. no safe way: a power pellet reachable ahead of the ghosts, else the most room, then the farthest ghost
  best = smallest(open, 'power', 59.9);
  if (best) return best;
  for (i = 0; i < open.length; i++) { a = open[i]; o = s[a]; if (!best || o.room > s[best].room || (o.room === s[best].room && o.ghost > s[best].ghost)) best = a; }
  return best;
}
